#!/usr/bin/env bash
# bitnami/postgresql 18.6.7 - base variant: existing-secret
# Path: pull the package, render this base variant locally, read the objects,
# then apply them with kubectl. No ConfigHub account is needed.
# Generated by scripts/generate-public-site.mjs from the committed package
# data for this base variant. Chart page: https://confighub.github.io/helm-expt/site/charts/bitnami-postgresql-18-6-7.html
set -euo pipefail

say() { printf '\n>> %s\n' "$*"; }

if ! command -v cub >/dev/null 2>&1; then
  printf 'cub is not installed. Install the cub CLI with:\n  curl -fsSL https://hub.confighub.com/cub/install.sh | bash\nthen add ~/.confighub/bin to your PATH and re-run this script.\n' >&2
  exit 1
fi

# Installer is a cub plugin. Check it before this script does any work.
if ! cub installer --help >/dev/null 2>&1; then
  printf 'The cub installer plugin is missing. Follow https://confighub.github.io/helm-expt/site/try.html#install-cub, then re-run this script.\n' >&2
  exit 1
fi

if ! command -v kustomize >/dev/null 2>&1; then
  printf 'kustomize is missing. Follow https://confighub.github.io/helm-expt/site/try.html#install-cub, then re-run this script.\n' >&2
  exit 1
fi

if ! command -v kubectl >/dev/null 2>&1; then
  printf 'kubectl is required for the apply step.\n' >&2
  exit 1
fi

say "Pull the package and render the existing-secret base variant into ./bitnami-postgresql-18-6-7-existing-secret"
cub installer setup --pull oci://europe-west1-docker.pkg.dev/nth-fort-499605-q5/helm-expt/bitnami-postgresql:18.6.7@sha256:fccd0da443cb3d0360e6a15f6ada67162f04261da38a071eaad2e97786b307d8 --base existing-secret --work-dir ./bitnami-postgresql-18-6-7-existing-secret --non-interactive --namespace postgresql

say "Read what was rendered; nothing has touched the cluster yet"
ls ./bitnami-postgresql-18-6-7-existing-secret/out/manifests

say "Ensure the postgresql namespace exists"
kubectl create namespace postgresql --dry-run=client -o yaml | kubectl apply -f -

say "Requirement before apply: Secret postgresql/postgresql-auth key postgres-password"
if ! kubectl -n postgresql create secret generic postgresql-auth --from-literal=postgres-password="$(openssl rand -base64 32)"; then
  printf '!! The requirement command failed. If the resource already exists, review it and re-run; otherwise fix the error above.\n' >&2
  exit 1
fi

if [ -d ./bitnami-postgresql-18-6-7-existing-secret/out/secrets ]; then
  say "Apply rendered Secrets first"
  kubectl apply -f ./bitnami-postgresql-18-6-7-existing-secret/out/secrets
fi

say "Apply the rendered objects"
kubectl apply -f ./bitnami-postgresql-18-6-7-existing-secret/out/manifests

say "Done. The cluster received exactly the files in ./bitnami-postgresql-18-6-7-existing-secret/out."
